insert into public.posts(title,slug,category,date,image,excerpt,body,sort_order,published) select title,slug,category,date,image,excerpt,body,sort_order,published from jsonb_populate_recordset(null::public.posts,$j$[{"title":"Design systems that actually scale","slug":"design-systems-that-scale","category":"Systems","date":"2026-05-12","image":"/projects/p1.svg","excerpt":"A small set of rules beats a giant component library.","body":"A small set of rules beats a giant component library.\n\nStart with the problem, not the screen. Map the people, the moment and the outcome before opening your design tool.\n\nThen build small, test early and keep a changelog so everyone can see why decisions were made.","sort_order":1,"published":true},{"title":"User research in one week","slug":"research-in-a-week","category":"Research","date":"2026-06-12","image":"/projects/p2.svg","excerpt":"A lightweight sprint for teams with no research budget.","body":"A lightweight sprint for teams with no research budget.\n\nStart with the problem, not the screen. Map the people, the moment and the outcome before opening your design tool.\n\nThen build small, test early and keep a changelog so everyone can see why decisions were made.","sort_order":2,"published":true},{"title":"Small details that create delight","slug":"designing-for-delight","category":"Craft","date":"2026-07-12","image":"/projects/p3.svg","excerpt":"Micro-interactions that earn their place.","body":"Micro-interactions that earn their place.\n\nStart with the problem, not the screen. Map the people, the moment and the outcome before opening your design tool.\n\nThen build small, test early and keep a changelog so everyone can see why decisions were made.","sort_order":3,"published":true},{"title":"Developer handoff without tears","slug":"handoff-without-tears","category":"Process","date":"2026-08-12","image":"/projects/p4.svg","excerpt":"How to ship pixel-true work with fewer meetings.","body":"How to ship pixel-true work with fewer meetings.\n\nStart with the problem, not the screen. Map the people, the moment and the outcome before opening your design tool.\n\nThen build small, test early and keep a changelog so everyone can see why decisions were made.","sort_order":4,"published":true}]$j$::jsonb) where not exists (select 1 from public.posts);
